function validation(){return validationSurfaceHTML(project(),7,{title:'Make the technology choices reviewable',purpose:'Review selection rationale, capability fulfillment, suitability evidence and external approval.',run:B('run-checks','Run checks','primary'),findings:findings().map(f=>({...f,reference:record(f.objectId)?.ref||f.objectId,actions:B('fix','Open remedy','',{'data-tr-id':f.id})}))});}
 function fix(id){
  const f=findings().find(f=>f.id===id);if(!f)return;close(true);
  if(f.code==='intake')return intake();if(f.code==='design-question'){document.dispatchEvent(new CustomEvent('aiw:inspect-record',{detail:{id:f.objectId,chapter:7}}));return;}
  if(f.code==='unrealized')return showGhost('missing',f.objectId);
  // A connection finding identifies the connection, not a realization. Open the actual
  // interface editor so an invalid endpoint can be replaced in the same workflow.
  const connectionId=f.connectionId||(f.code==='connection-endpoint'?f.objectId:null);
  if(connectionId)return editConnection(connectionId);
  if(f.code==='broken-map'){
   const mapping=model().mappings.find(m=>m.id===f.objectId),r=record(mapping?.realizationId);
   if(r){activeId=r.id;bridge.state.selected=r.id;return editPlan(r.id,0)}
   return dialog('Repair '+f.objectId+' allocation','<p>This allocation refers to a realization that is no longer in the working design. Review the missing endpoint before carrying Chapter 7 forward.</p><p>Its capability can be inspected in Chapter 6; an existing realization can be edited from Chapter 7 Work.</p><div class="l-sol-actions"><a class="btn primary" href="'+esc(projectURL('/?chapter=7&tab=work'))+'">Review realization plans</a><a class="btn" href="'+esc(projectURL('/?chapter=6&tab=work'))+'">Review capabilities in Chapter 6</a></div>','repair-mapping');
  }
  const r=record(f.objectId);if(!r)return bridge.toast('This finding refers to a missing record. Review its source and the current realization plans.');
  activeId=r.id;bridge.state.selected=r.id;
  if(['criterion','coverage-gap'].includes(f.code)){const o=realizationOption(r);return o?editAssessment(o.id,f.criterionId):goCompare()}
  if(['product','specification','evidence','tradeoff'].includes(f.code))return editOption(realizationOption(r)?.id);
  if(['choice','comparison'].includes(f.code))return goCompare();
  if(f.code==='record')return recordSelection();if(f.code==='approval')return approval();
  editPlan(r.id,['definition','mapping-scope','source-change'].includes(f.code)?0:['rationale','risks','assumptions','capacity','cost','estimate'].includes(f.code)?2:1);
 }
