 document.addEventListener('change',e=>{if(e.target.name==='activeRecord')return setRecord(e.target.value);if(e.target.name==='libraryProduct'&&e.target.value){editOption(null,e.target.value);e.target.value='';return}if(e.target.name==='sensitivityDriver'){const d=sources(current()?.id).drivers.find(x=>x.id===e.target.value);sensitivity={realizationId:current()?.id,driverId:e.target.value,revision:store.value.revision};const panel=e.target.closest('.tr-sensitivity');if(panel){panel.querySelector('[name=sensitivityPriority]').value='';panel.querySelector('[name=sensitivityTarget]').value='';}const hint=document.querySelector('#tr-target-hint');if(hint)hint.textContent='Recorded: '+(d?.metric||'Measure not stated')+' · '+targetText(d)+' · '+(driverPriority(d)||'Priority open')+'. Use the same unit; this is a scenario, not a measurement.';const result=document.querySelector('.tr-sensitivity-result');if(result)result.textContent='Change this driver’s priority or numeric target, then explore impact.';return}if((e.target.name||'').startsWith('compare:')){const i=Number(e.target.name.split(':')[1]),old=pair[i];pair[i]=e.target.value;if(pair[1-i]===pair[i])pair[1-i]=old;bridge.render();return}if(!e.target.closest('.tr-dialog form'))return;dirty=true;if(e.target.name==='product'&&e.target.form?.id==='tr-option-form'){const form=e.target.form;try{context.configurationFacts=configurationFactsFromForm(form,context.configurationFacts||{})||{};form.querySelector('[data-tr-configuration-fields]').innerHTML=configurationFieldsHTML({product:e.target.value,configurationFacts:context.configurationFacts});}catch(e){error(e.message);}}if(e.target.name==='capabilityIds'){const d=document.querySelector('[data-tr-scope="'+e.target.value+'"]');if(d)d.hidden=!e.target.checked}},{signal});
