 document.addEventListener('submit',async e=>{if(!e.target.closest('.tr-dialog'))return;e.preventDefault();const f=e.target;if(!validateForm(f))return;const fd=new FormData(f),raw=Object.fromEntries(fd);if(f.id==='record-retire-form'){await send('record.retire',{ids:context.ids,reason:raw.reason,chapter:7},'Retired with your reason. You can restore it.');return;}if(f.id==='tr-preference-form'){await send('preference',{id:context.id,optionId:raw.optionId},'Draft preference saved.');return;}else if(f.id==='tr-plan-form'){const data=readPlan(f);if(context.type==='ghost')await send('proposal',{key:ghost.key,objectId:ghost.objectId,record:data,mappings:data.mappings,reviewed:data.reviewed},'Reviewed implementation proposal saved.');else await send('plan',{...data,id:context.id});}else if(f.id==='tr-option-form'){try{const configurationFacts=configurationFactsFromForm(f,context.configurationFacts||{});await send('option',{id:context.id,option:{...raw,id:context.optionId,configurationFacts}});}catch(e){error(e.message);}}else if(f.id==='tr-assessment-form')await send('assessment',{...raw,...context});else if(f.id==='tr-record-form')await send('record',{id:context.id,reviewed:fd.has('reviewed')},'Architect selection recorded. External approval remains separate.');else if(f.id==='tr-approval-form')await send('approval',{...raw,id:context.id,confirmed:fd.has('confirmed')},'External approval evidence attached to this selection revision.');else if(f.id==='tr-connection-form')await send('connection',{...raw,id:context.id});else if(f.id==='tr-remove-form')await send('remove-connection',{id:context.id});else if(f.id==='tr-intake-form')await send('intake',{},'Logical technology inputs reviewed.');else if(f.id==='tr-handoff-form')await send('handoff',{acknowledge:fd.has('acknowledge')},'Technology realizations carried into Chapter 8.',chapter8);},{signal});
